use std::path::PathBuf;

use olaya::{BuiltinFamilies, Engine};

fn registry_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../registry")
}

#[test]
fn registry_builds_a_valid_catalog_bundle() {
    let manifests = olaya::load_manifests(registry_dir()).expect("registry loads");
    assert!(!manifests.is_empty());
    // `registry-catalog.json` is a release asset generated by CI, not a
    // checked-in file. Validate that the manifest source can produce it.
    let bundle = olaya::CatalogBundle::new(manifests.clone());
    bundle.validate().expect("catalog bundle validates");
    assert_eq!(bundle.manifests, manifests);
    let bytes = serde_json::to_vec(&bundle).expect("serialize catalog bundle");
    let parsed: olaya::CatalogBundle =
        serde_json::from_slice(&bytes).expect("parse catalog bundle");
    assert_eq!(parsed, bundle);
}

#[test]
fn catalog_exposes_the_laya_checkpoints_the_router_and_nli() {
    let manifests = olaya::load_manifests(registry_dir()).expect("registry loads");
    assert_eq!(manifests.len(), 21);
    let engine = Engine::builder()
        .builtin_families(BuiltinFamilies::all())
        .manifests(manifests)
        .build()
        .expect("engine builds");
    let names = engine
        .list_models()
        .into_iter()
        .map(|model| model.name)
        .collect::<Vec<_>>();

    for expected in [
        "laya",
        "laya:en",
        "laya-multilingual",
        "laya:multilingual",
        "laya-typed-decisions",
        "laya:typed-decisions",
        "laya-latest",
        "laya:latest",
        "nli-modernbert",
        "nli:modernbert-large",
        "nli-modernbert-base",
        "nli:modernbert-base",
        "nli-deberta-v3",
        "nli:deberta-v3-large",
        "gliclass-v4-edge",
        "gliclass:v4-edge",
        "gliclass-instruct-edge",
        "gliclass:instruct-edge",
        "gliclass-large",
        "gliclass",
        "gliclass:latest",
        "gliclass:large",
        "von",
        "von:1.1",
        "von:latest",
        "decima-small",
        "decima:small",
        "decima-base",
        "decima:base",
        "decima:latest",
        "decima-base-clean",
        "decima:base-clean",
        "decima-agent",
        "decima:agent",
        "decima-guard",
        "decima:guard",
        "decima-guard-small",
        "decima:guard-small",
        "qwen3guard",
        "qwen3guard-gen-0.6b",
        "qwen3guard:0.6b",
        "qwen3guard:latest",
        "decision-eos-0.8b",
        "decision:eos",
        "decision:0.8b",
        "decision:latest",
        "kev-0.8b",
        "kev",
        "kev:0.8b",
        "kev:latest",
        "clef-flash",
        "clef",
        "clef:flash",
        "clef:latest",
    ] {
        assert!(
            names.iter().any(|name| name == expected),
            "missing {expected}: {names:?}"
        );
    }

    let router = engine.resolve("laya-latest").expect("router manifest");
    assert_eq!(router.engine, "router");
    let router = router.router.expect("router config");
    assert_eq!(router.strategy, "script");
    assert_eq!(router.default, "laya");
    assert_eq!(router.routes.get("english"), Some(&"laya".to_owned()));
    assert_eq!(
        router.routes.get("multilingual"),
        Some(&"laya-multilingual".to_owned())
    );
}
